import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        return

    list1 = list(map(int, data[1:1+n]))
    list2 = list(map(int, data[1+n:1+2*n]))

    add = lambda a, b: a + b
    result = [add(x, y) for x, y in zip(list1, list2)]

    for val in result:
        print(val)

if __name__ == "__main__":
    main()
